<?php
$error='';$success=false;$u=socialUser();$kind=(string)($_GET['kind']??'place');$target=(string)($_GET['target']??'');
if(!$u||!journeyEnabled()){http_response_code(403);$error='FEATURE_DISABLED';}
elseif($_SERVER['REQUEST_METHOD']==='POST')try{
 if(($_POST['feedback_action']??'')==='appeal'){journeyReviewAppeal((string)$_POST['review'],(int)$_POST['revision'],(string)$_POST['reason']);$success=true;}
 elseif(($_POST['feedback_action']??'')==='report'){journeyReport(['place'=>$target,'type'=>$_POST['type']??'','observed_at'=>strtotime((string)($_POST['observed_on']??''))?:0,'evidence'=>$_POST['evidence']??'']);$success=true;}
 else{journeyReview(['kind'=>$kind,'target'=>$target,'visited_on'=>$_POST['visited_on']??'','rating'=>(int)($_POST['rating']??0),'body'=>$_POST['body']??'','expected_revision'=>(int)($_POST['revision']??0)]);$success=true;}
}catch(DomainException $e){$error=$e->getMessage();http_response_code(422);}
$title=jt('feedback');ob_start();?><section class="page-heading"><h1><?=e($title)?></h1><p><?=e(jt('self_report'))?></p></section><?php if($error):?><p role="alert"><?=e(jt($error))?></p><?php elseif($success):?><p role="status"><?=e(cmAutoEnabled()?crT('approved'):jt('pending'))?></p><?php endif?>
<?php if($u&&journeyEnabled()):$mine=jq('SELECT * FROM journey_reviews WHERE owner=? AND kind=? AND target=?',[$u['id'],$kind,$target])->fetch();?><form method="post" class="form-panel"><?=csrf()?><input type="hidden" name="feedback_action" value="review"><input type="hidden" name="revision" value="<?=(int)($mine['revision']??0)?>"><label><?=e(jt('date'))?><input type="date" name="visited_on" required max="<?=date('Y-m-d')?>"></label><label><?=e(jt('rating'))?><select name="rating"><?php for($j=1;$j<=5;$j++):?><option><?=$j?></option><?php endfor?></select></label><label><?=e(jt('feedback'))?><textarea name="body" minlength="10" maxlength="3000" required></textarea></label><button class="button"><?=e(jt('submit_review'))?></button></form>
<?php if($mine):$decision=jq("SELECT reason FROM journey_decisions WHERE kind='review' AND target=? ORDER BY id DESC LIMIT 1",[$mine['id']])->fetchColumn();?><section class="form-panel"><p><?=e(jt($mine['state']))?></p><?php if($decision):?><p><?=e($decision)?></p><?php endif?><?php if(in_array($mine['state'],['rejected','blocked'],true)):?><form method="post"><?=csrf()?><input type="hidden" name="feedback_action" value="appeal"><input type="hidden" name="review" value="<?=e($mine['id'])?>"><input type="hidden" name="revision" value="<?=(int)$mine['revision']?>"><label><?=e(jt('appeal_reason'))?><textarea name="reason" required minlength="10" maxlength="2000"></textarea></label><button><?=e(jt('appeal'))?></button></form><?php endif?></section><?php endif?>
<?php if($kind==='place'):?><form method="post" class="form-panel"><?=csrf()?><input type="hidden" name="feedback_action" value="report"><h2><?=e(jt('report'))?></h2><label><?=e(jt('report_type'))?><select name="type"><?php foreach(['closed','hours','price','access'] as $code):?><option value="<?=$code?>"><?=e(jt('report_'.$code))?></option><?php endforeach?></select></label><label><?=e(jt('observed'))?><input type="date" name="observed_on" required max="<?=date('Y-m-d')?>"></label><label><?=e(jt('private_evidence'))?><textarea name="evidence" minlength="10" maxlength="4000" required></textarea></label><button class="button"><?=e(jt('submit_review'))?></button></form><?php endif?>
<section class="form-panel"><h2><?=e(jt('my_reports'))?></h2><?php foreach(jq('SELECT type,state,reason,created FROM journey_reports WHERE owner=? ORDER BY created DESC LIMIT 30',[$u['id']]) as $row):?><p><?=e(jt('report_'.$row['type']).' · '.jt($row['state']).' · '.date('Y-m-d',$row['created']).' · '.$row['reason'])?></p><?php endforeach?></section><?php endif?>
<?php $content=ob_get_clean();require ROOT.'/views/layout.php';exit;
